'use client';
import { useState, useEffect } from 'react';
import axios from 'axios';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { 
  Save as SaveIcon, 
  ArrowBack as ArrowBackIcon,
  Person as PersonIcon,
  Search as SearchIcon,
  Clear as ClearIcon
} from '@mui/icons-material';
import Layout from "..//../components/Layout";

export default function EditGroupe() {
  const router = useRouter();
  const { id } = router.query;
  
  const [loading, setLoading] = useState(true);
  const [groupe, setGroupe] = useState(null);
  const [allEligibleStudents, setAllEligibleStudents] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudents, setSelectedStudents] = useState([]);
  const [groupName, setGroupName] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  // Fetch group data when component mounts
  useEffect(() => {
    if (id) {
      fetchGroupData();
    }
  }, [id]);

  const fetchGroupData = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`http://localhost:5000/api/groupes/edit/${id}`);
      
      const { groupe, eligibleStudents } = response.data;
      
      setGroupe(groupe);
      setGroupName(groupe.nomGroupe);
      setSelectedStudents(groupe.etudiants || []);
      setAllEligibleStudents(eligibleStudents);
    } catch (error) {
      console.error("Erreur lors de la récupération des données du groupe:", error);
      setErrorMessage("Impossible de charger les données du groupe");
    } finally {
      setLoading(false);
    }
  };

  // Filtered students based on search term
  const filteredStudents = allEligibleStudents.filter(student => 
    !selectedStudents.some(s => s.idEtudiant === student.idEtudiant) && 
    (`${student.nom} ${student.prenom}`.toLowerCase().includes(searchTerm.toLowerCase()) || 
     `${student.prenom} ${student.nom}`.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const addStudent = (student) => {
    setSelectedStudents(prev => [...prev, student]);
  };

  const removeStudent = (idEtudiant) => {
    setSelectedStudents(prev => prev.filter(s => s.idEtudiant !== idEtudiant));
  };

  const handleSaveGroup = async () => {
    // Validate group name
    if (!groupName.trim()) {
      setErrorMessage("Le nom du groupe est requis");
      return;
    }

    try {
      // Save group name if changed
      if (groupName !== groupe.nomGroupe) {
        await axios.put(`http://localhost:5000/api/groupes/${id}`, {
          nomGroupe: groupName
        });
      }

      // Update group composition
      await axios.put(`http://localhost:5000/api/groupes/composition/${id}`, {
        etudiants: selectedStudents.map(s => s.idEtudiant)
      });

      setSuccessMessage("Groupe mis à jour avec succès");
      setTimeout(() => {
        router.push('/gestion-groupes');
      }, 1500);
    } catch (error) {
      console.error("Erreur lors de la mise à jour du groupe:", error);
      setErrorMessage(error.response?.data?.message || "Erreur lors de la mise à jour du groupe");
    }
  };

  if (loading) {
    return (
      <Layout title="Modification du groupe">
        <div className="flex justify-center items-center h-64">
          <p className="text-lg">Chargement des données...</p>
        </div>
      </Layout>
    );
  }

  if (!groupe) {
    return (
      <Layout title="Modification du groupe">
        <div className="p-4">
          <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">
            <p>Groupe non trouvé ou erreur lors du chargement.</p>
            <Link href="/gestion-groupes">
              <button className="mt-4 px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600">
                Retour à la liste des groupes
              </button>
            </Link>
          </div>
        </div>
      </Layout>
    );
  }

  return (
    <Layout title="Modification du groupe">
      <div className="p-4 max-w-6xl mx-auto">
        {/* Header with navigation */}
        <div className="flex justify-between items-center mb-6">
          <Link href="/gestion-groupes">
            <button className="flex items-center text-blue-600 hover:text-blue-800">
              <ArrowBackIcon className="mr-1" /> Retour aux groupes
            </button>
          </Link>
          <h1 className="text-2xl font-bold text-center text-[#2563EB]">
            Modification du groupe
          </h1>
          <div></div> {/* Empty div for flex alignment */}
        </div>

        {/* Alert messages */}
        {errorMessage && (
          <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
            {errorMessage}
            <button 
              className="float-right" 
              onClick={() => setErrorMessage('')}
            >
              <ClearIcon />
            </button>
          </div>
        )}
        
        {successMessage && (
          <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded mb-4">
            {successMessage}
          </div>
        )}

        {/* Group editing form */}
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
          <div className="mb-6">
            <label className="block text-gray-700 font-medium mb-2">
              Nom du groupe
            </label>
            <input
              type="text"
              value={groupName}
              onChange={(e) => setGroupName(e.target.value)}
              className="w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
              placeholder="Nom du groupe"
            />
          </div>
          
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Available students */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-medium mb-3 text-gray-700 flex justify-between items-center">
                <span>Étudiants disponibles</span>
                <span className="text-sm text-gray-500">{filteredStudents.length} étudiants</span>
              </h3>
              
              <div className="mb-3 relative">
                <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <SearchIcon className="text-gray-400" style={{ fontSize: '1.2rem' }} />
                </div>
                <input
                  type="text"
                  placeholder="Rechercher un étudiant..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-10 p-2 border rounded focus:ring-2 focus:ring-blue-500 focus:outline-none"
                />
                {searchTerm && (
                  <button
                    onClick={() => setSearchTerm('')}
                    className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                  >
                    <ClearIcon style={{ fontSize: '1.2rem' }} />
                  </button>
                )}
              </div>
              
              <div className="overflow-y-auto max-h-64 border rounded bg-white">
                {filteredStudents.length > 0 ? (
                  <ul className="divide-y divide-gray-200">
                    {filteredStudents.map(student => (
                      <li 
                        key={student.idEtudiant}
                        className="p-2 hover:bg-blue-50 cursor-pointer transition-colors flex justify-between items-center"
                        onClick={() => addStudent(student)}
                      >
                        <div className="flex items-center">
                          <PersonIcon className="text-gray-400 mr-2" style={{ fontSize: '1.2rem' }} />
                          <span>{student.nom} {student.prenom}</span>
                        </div>
                        <button className="text-blue-500 hover:text-blue-700 text-xs font-medium">
                          + Ajouter
                        </button>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <div className="p-4 text-center text-gray-500">
                    {searchTerm ? "Aucun étudiant trouvé" : "Aucun étudiant disponible"}
                  </div>
                )}
              </div>
            </div>
            
            {/* Selected students */}
            <div className="bg-gray-50 p-4 rounded-lg">
              <h3 className="font-medium mb-3 text-gray-700 flex justify-between items-center">
                <span>Étudiants du groupe</span>
                <span className="text-sm text-gray-500">{selectedStudents.length} sélectionnés</span>
              </h3>
              
              <div className="overflow-y-auto max-h-64 border rounded bg-white">
                {selectedStudents.length > 0 ? (
                  <ul className="divide-y divide-gray-200">
                    {selectedStudents.map(student => (
                      <li 
                        key={student.idEtudiant}
                        className="p-2 hover:bg-red-50 transition-colors flex justify-between items-center"
                      >
                        <div className="flex items-center">
                          <PersonIcon className="text-blue-400 mr-2" style={{ fontSize: '1.2rem' }} />
                          <span>{student.nom} {student.prenom}</span>
                        </div>
                        <button 
                          onClick={() => removeStudent(student.idEtudiant)}
                          className="text-red-500 hover:text-red-700 text-xs font-medium"
                        >
                          Retirer
                        </button>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <div className="p-8 text-center text-gray-500">
                    Aucun étudiant dans ce groupe
                  </div>
                )}
              </div>
            </div>
          </div>
          
          <div className="mt-6 flex justify-end">
            <button
              onClick={handleSaveGroup}
              className="px-6 py-2 bg-[#2563EB] text-white rounded-lg hover:bg-[#1D4ED8] transition-colors flex items-center"
            >
              <SaveIcon className="mr-2" /> Enregistrer les modifications
            </button>
          </div>
        </div>
      </div>
    </Layout>
  );
}